// Call the function to retrieve the linked libavutil version constant
unsigned v = avutil_version();
(void)v; // value is used for coverage only
// Validation: No ownership or additional constraints; simply calling exercises the path.

// Retrieve a human-readable version string; do not parse, modify, or free
const char *ver = av_version_info();
(void)ver; // use for coverage only
// Validation: Pointer is owned by the library; no freeing or parsing performed.

// Retrieve build-time configuration string; do not modify or free
const char *cfg = avutil_configuration();
(void)cfg;
// Validation: Library-owned static string; no parsing, modification, or freeing.

// Retrieve license text; do not modify or free
const char *lic = avutil_license();
(void)lic;
// Validation: Library-owned static string; no parsing, modification, or freeing.

// Generate a (possibly invalid) enum value; handle NULL return
unsigned raw = *FUZZ_PARAM(unsigned int);
// Intentionally allow out-of-range values to cover NULL-paths (unknown types)
enum AVMediaType mt = (enum AVMediaType)((int)(raw % 8) - 1); // yields -1..6
const char *mt_str = av_get_media_type_string(mt);
(void)mt_str; // may be NULL
// Validation: Properly handles potential NULL return and does not free/modify the string.

// Generate a (possibly invalid) picture type to cover both known and unknown cases
unsigned raw = *FUZZ_PARAM(unsigned int);
enum AVPictureType pt = (enum AVPictureType)(raw % 16); // may exceed known values
char c = av_get_picture_type_char(pt);
(void)c;
// Validation: Function returns '?' for unknown types; no further constraints.

// Choose a valid element size among {1,2,4,8}
unsigned sel = *FUZZ_PARAM(unsigned int) % 4;
unsigned elsize = sel == 0 ? 1 : (sel == 1 ? 2 : (sel == 2 ? 4 : 8));
// Choose a small element count for performance and to ensure bounded memory
unsigned count = *FUZZ_PARAM(unsigned int) % 32; // number of non-terminator elements
// Generate a random terminator value (masked to elsize bytes)
uint64_t term64 = *FUZZ_PARAM(uint64_t);
uint64_t term_masked = term64 & (elsize == 8 ? ~0ULL : ((1ULL << (elsize * 8)) - 1ULL));
// Allocate (count + 1) elements and fill with fuzz data making sure last element equals term
const std::string src = FUZZ_PARAM_STR();
size_t src_idx = 0;
auto next_byte = [&](void) -> uint8_t {
    if (src.empty()) return 0;
    uint8_t b = (uint8_t)src[src_idx];
    src_idx = (src_idx + 1) % src.size();
    return b;
};
std::vector<uint8_t> buf((count + 1) * elsize);
// Serialize term into a temporary byte array
uint8_t term_bytes[8];
for (unsigned i = 0; i < elsize; ++i) term_bytes[i] = (uint8_t)((term_masked >> (i * 8)) & 0xFF);
// Fill non-terminator elements with random bytes; avoid accidental early terminator to improve coverage
for (unsigned i = 0; i < count; ++i) {
    uint8_t *e = &buf[i * elsize];
    for (unsigned j = 0; j < elsize; ++j) e[j] = next_byte();
    // If this element equals term, tweak one byte
    bool eq = true;
    for (unsigned j = 0; j < elsize; ++j) { if (e[j] != term_bytes[j]) { eq = false; break; } }
    if (eq) e[0] ^= 0x01; // ensure not equal to terminator
}
// Place the terminator as the last element
for (unsigned j = 0; j < elsize; ++j) buf[count * elsize + j] = term_bytes[j];
// Invoke the target
unsigned len = av_int_list_length_for_size(elsize, (const void*)buf.data(), term_masked);
// Property: with construction above, the first terminator is at index 'count'
FUZZ_ASSERT(len == count, "av_int_list_length_for_size should return the number of elements before the terminator");
// Validation: elsize is valid (1/2/4/8), list is properly terminated within allocated bounds, and term fits the element size.

// Retrieve the global time base as a rational and validate basic invariants
AVRational tb = av_get_time_base_q();
// Expected to be positive (commonly {1, AV_TIME_BASE}); enforce non-zero denominator
FUZZ_ASSERT(tb.den > 0, "time base denominator must be positive");
FUZZ_ASSERT(tb.num > 0, "time base numerator must be positive");
(void)tb;
// Validation: No ownership; asserts capture fundamental properties of a valid time base.

// Prepare a writable buffer >= AV_FOURCC_MAX_STRING_SIZE; 64 is a safe upper bound
char buf[64];
uint32_t fourcc = *FUZZ_PARAM(unsigned int);
char *ret = av_fourcc_make_string(buf, fourcc);
// The function should return the provided buffer pointer
FUZZ_ASSERT(ret == buf, "av_fourcc_make_string must return the input buffer pointer");
// Optionally touch the buffer to ensure it was written
volatile char sink = buf[0];
(void)sink;
// Validation: Buffer is writable and sufficiently large; return pointer is validated; no ownership issues.

// Choose a valid printf-style format and supply matching arguments
unsigned int choice = *FUZZ_PARAM(unsigned int) % 3;
const char *fmt = nullptr;
int level_candidates[] = { -8, 0, 8, 16, 24, 32, 40, 48, 56 }; // typical FFmpeg log levels
int level = level_candidates[*FUZZ_PARAM(unsigned int) % (sizeof(level_candidates)/sizeof(level_candidates[0]))];

// Build an optional AVClass-enabled dummy context; or pass NULL
struct DummyCtx { AVClass *av_class; } dummy{nullptr};
AVClass cls{};
cls.class_name = "fuzzctx";
cls.item_name = +[](void *ctx) -> const char* { (void)ctx; return "fuzzctx"; };
dummy.av_class = &cls;
void *avcl = (*FUZZ_PARAM(unsigned int) % 2) ? (void *)&dummy : (void *)nullptr;

// Pick format and call av_log with matching arguments
if (choice == 0) {
    fmt = "static message"; // no variadic args
    av_log(avcl, level, fmt);
} else if (choice == 1) {
    fmt = "int:%d";
    int v = (int)(*FUZZ_PARAM(unsigned int) & 0x7fffffff);
    av_log(avcl, level, fmt, v);
} else {
    fmt = "str:%s num:%d";
    std::string s = FUZZ_PARAM_STR();
    int v = (int)(*FUZZ_PARAM(unsigned int) & 0x7fffffff);
    av_log(avcl, level, fmt, s.c_str(), v);
}
// No persistent outputs

// av_log_once requires a state initialized to 0 before first use and reused across calls.
// Use an attribute to ensure one-time initialization.
if (!FUZZ_GET_ATTR_INT(state, "init")) {
    *state = 0;
    FUZZ_SET_ATTR_INT(state, "init", 1);
}

// Prepare dummy AVClass-enabled context (or NULL) for avcl
struct DummyCtx { AVClass *av_class; } dummy{nullptr};
AVClass cls{};
cls.class_name = "fuzzctx";
cls.item_name = +[](void *ctx) -> const char* { (void)ctx; return "fuzzctx"; };
dummy.av_class = &cls;
void *avcl = (*FUZZ_PARAM(unsigned int) % 2) ? (void *)&dummy : (void *)nullptr;

// Select levels from typical FFmpeg log levels
int level_candidates[] = { -8, 0, 8, 16, 24, 32, 40, 48, 56 };
int initial_level    = level_candidates[*FUZZ_PARAM(unsigned int) % (sizeof(level_candidates)/sizeof(level_candidates[0]))];
int subsequent_level = level_candidates[*FUZZ_PARAM(unsigned int) % (sizeof(level_candidates)/sizeof(level_candidates[0]))];

// Pick format and call with matching arguments; ensure printf contract is respected
unsigned int choice = *FUZZ_PARAM(unsigned int) % 3;
if (choice == 0) {
    av_log_once(avcl, initial_level, subsequent_level, state, "once: static");
} else if (choice == 1) {
    int v = (int)(*FUZZ_PARAM(unsigned int) & 0x7fffffff);
    av_log_once(avcl, initial_level, subsequent_level, state, "once: v=%d", v);
} else {
    std::string s = FUZZ_PARAM_STR();
    int v = (int)(*FUZZ_PARAM(unsigned int) & 0x7fffffff);
    av_log_once(avcl, initial_level, subsequent_level, state, "once: %s %d", s.c_str(), v);
}
// Return state as output to keep it persistent

// av_vlog requires a valid AVClass-enabled context and a va_list corresponding to fmt.
// Build a minimal dummy AVClass-enabled context
struct DummyCtx { AVClass *av_class; } dummy{nullptr};
AVClass cls{};
cls.class_name = "fuzzctx";
cls.item_name = +[](void *ctx) -> const char* { (void)ctx; return "fuzzctx"; };
dummy.av_class = &cls;
void *avcl = (void *)&dummy;

int level_candidates[] = { -8, 0, 8, 16, 24, 32, 40, 48, 56 };
int level = level_candidates[*FUZZ_PARAM(unsigned int) % (sizeof(level_candidates)/sizeof(level_candidates[0]))];

// Helper to construct va_list and forward to av_vlog
auto vlog_invoke = [&](void *ctx, int lvl, const char *fmt, ...) {
    va_list vl; va_start(vl, fmt);
    av_vlog(ctx, lvl, fmt, vl);
    va_end(vl);
};

unsigned int choice = *FUZZ_PARAM(unsigned int) % 3;
if (choice == 0) {
    vlog_invoke(avcl, level, "vlog static");
} else if (choice == 1) {
    int v = (int)(*FUZZ_PARAM(unsigned int) & 0x7fffffff);
    vlog_invoke(avcl, level, "vlog %d", v);
} else {
    std::string s = FUZZ_PARAM_STR();
    int v = (int)(*FUZZ_PARAM(unsigned int) & 0x7fffffff);
    vlog_invoke(avcl, level, "vlog %s %d", s.c_str(), v);
}
// No persistent outputs

// Simply query current global log level to exercise accessor
int lvl = av_log_get_level();
// Basic sanity: levels are typically between -8 and 56; do not assert hard, just touch value
(void)lvl; // prevent unused warning

// Set to a valid log level from the known set
int level_candidates[] = { -8, 0, 8, 16, 24, 32, 40, 48, 56 };
int level = level_candidates[*FUZZ_PARAM(unsigned int) % (sizeof(level_candidates)/sizeof(level_candidates[0]))];
av_log_set_level(level);
// Optionally read back to exercise the getter path as well
(void)av_log_get_level();

// Install the default callback (valid, thread-safe per FFmpeg) to exercise setter
void (*cb)(void*, int, const char*, va_list) = av_log_default_callback;
av_log_set_callback(cb);
// No persistent outputs; the runtime may call other stubs that generate logs afterwards

// Prepare AVClass-enabled dummy context and a va_list, then invoke the default callback
struct DummyCtx { AVClass *av_class; } dummy{nullptr};
AVClass cls{};
cls.class_name = "fuzzctx";
cls.item_name = +[](void *ctx) -> const char* { (void)ctx; return "fuzzctx"; };
dummy.av_class = &cls;

int level_candidates[] = { -8, 0, 8, 16, 24, 32, 40, 48, 56 };
int level = level_candidates[*FUZZ_PARAM(unsigned int) % (sizeof(level_candidates)/sizeof(level_candidates[0]))];

auto call_default = [&](void *ctx, int lvl, const char *fmt, ...) {
    va_list vl; va_start(vl, fmt);
    av_log_default_callback(ctx, lvl, fmt, vl);
    va_end(vl);
};

unsigned int choice = *FUZZ_PARAM(unsigned int) % 3;
if (choice == 0) {
    call_default(&dummy, level, "def static");
} else if (choice == 1) {
    int v = (int)(*FUZZ_PARAM(unsigned int) & 0x7fffffff);
    call_default(&dummy, level, "def %d", v);
} else {
    std::string s = FUZZ_PARAM_STR();
    int v = (int)(*FUZZ_PARAM(unsigned int) & 0x7fffffff);
    call_default(&dummy, level, "def %s %d", s.c_str(), v);
}
// No outputs

// Provide an AVClass-enabled object and query its default item name
struct DummyCtx { AVClass *av_class; } dummy{nullptr};
AVClass cls{};
cls.class_name = "fuzzctx";
cls.item_name = +[](void *ctx) -> const char* { (void)ctx; return "fuzzctx"; };
dummy.av_class = &cls;

